mapper.select:
SELECT monthly_pick_id, member_id, pick_month, roastery, source_url, created_at
FROM monthly_pick
WHERE monthly_pick_id = #{monthlyPickId}
  AND member_id = #{memberId}

mapper.insert:
INSERT INTO monthly_pick_option (
  monthly_pick_id, raw_text, origin, producer, variety, process,
  dark_roast, decaf, sold_out, already_purchased
)
VALUES (
  #{monthlyPickId}, #{rawText}, #{origin}, #{producer}, #{variety}, #{process},
  #{darkRoast}, #{decaf}, #{soldOut}, #{alreadyPurchased}
)

mapper.update:
UPDATE monthly_pick_option
SET score = #{score},
    score_reason = #{scoreReason}
WHERE option_id = #{optionId}

mapper.select:
SELECT taste_rule_id, member_id, rule_type, tag, match_keywords, weight, reason
FROM taste_rule
WHERE member_id = #{memberId}
